  const [rotation, setRotation] = React.useState(0)
  const {
    currentPage,
    viewportElement,
    setViewportElement,
    measureScroll,
    handleScroll,
    scrollToPageArea,
    getViewportElement,
  } = usePdfScroll({
    pageCount: document.numPages,
    onVisiblePageChange,
    onScrollProgressChange,
