            <div data-slot="pdf-viewer-footer">{bottomSlot}</div>
          ) : null}
        </div>
        {rightRailSlot ? (
          <PdfViewerRail side="right" open={railsOpen} animate={showRailToggle}>
            {rightRailSlot}
          </PdfViewerRail>
        ) : null}
      </div>
    </div>
  )
