function PdfViewerInner({
  src,
  className,
  scale: controlledScale,
  defaultScale,
  onScaleChange,
  toolbar = true,
  downloadFileName,
  renderPageOverlay,
  onVisiblePageChange,
  onScrollProgressChange,
  bare = false,
  slots,
  railToggle,
  defaultRailsOpen,
