"content": "import * as React from "react"

import {
  getPdfVisiblePageNumbers,
  type PdfPageLayoutModel,
} from "./pdf-viewer-layout"

export function usePdfPageVirtualization({
  layout,
  viewportElement,
}: {
  layout: PdfPageLayoutModel
  viewportElement: HTMLDivElement | null
}) {
  const measureFrameRef = React.useRef(0)
  const [visiblePageNumbers, setVisiblePageNumbers] = React.useState<
    readonly number[]
  >(() => [1])

  const measureVisiblePagesNow = React.useCallback(() => {
    measureFrameRef.current = 0
    const scrollTop = viewportElement?.scrollTop ?? 0
    const viewportHeight = viewportElement?.clientHeight ?? 0
    const nextPageNumbers = getPdfVisiblePageNumbers({
      layout,
      scrollTop,
      viewportHeight,
    })
    setVisiblePageNumbers((previousPageNumbers) =>
      arePageNumbersEqual(previousPageNumbers, nextPageNumbers)
        ? previousPageNumbers
        : nextPageNumbers
    )
  }, [layout, viewportElement])
  const measureVisiblePagesNowRef = React.useRef(measureVisiblePagesNow)
  measureVisiblePagesNowRef.current = measureVisiblePagesNow

  const measureVisiblePages = React.useCallback(() => {
    if (measureFrameRef.current) return
    measureFrameRef.current = requestAnimationFrame(() =>
      measureVisiblePagesNowRef.current()
    )
  }, [])

  React.useEffect(() => {
    if (measureFrameRef.current) {
      cancelAnimationFrame(measureFrameRef.current)
      measureFrameRef.current = 0
    }
    measureVisiblePagesNow()
  }, [measureVisiblePagesNow])

  React.useEffect(
    () => () => {
      if (measureFrameRef.current) {
        cancelAnimationFrame(measureFrameRef.current)
      }
    },
    []
  )

  return { visiblePageNumbers, measureVisiblePages }
}

function arePageNumbersEqual(
  previousPageNumbers: readonly number[],
  nextPageNumbers: readonly number[]
) {
  if (previousPageNumbers.length !== nextPageNumbers.length) return false
  return previousPageNumbers.every(
    (pageNumber, index) => pageNumber === nextPageNumbers[index]
  )
}
",
"content": "import * as React from "react"
import {
  Maximize,
  Minus,
  PanelLeftClose,
  PanelLeftOpen,
  Plus,
  RotateCw,
} from "lucide-react"

import { type ViewerDownloadAction } from "@/lib/viewer-download"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { ViewerDownloadControl } from "@/components/ui/viewer-download"

export function PdfViewerToolbar({
  currentPage,
  pageCount,
  scale,
  downloadAction,
  showRailToggle,
  railsOpen,
  onToggleRails,
  onZoomOut,
  onZoomIn,
  onFitWidth,
  onRotate,
}: {
  currentPage: number
  pageCount: number
  scale: number
  downloadAction: ViewerDownloadAction
  showRailToggle: boolean
  railsOpen: boolean
  onToggleRails: () => void
  onZoomOut: () => void
  onZoomIn: () => void
  onFitWidth: () => void
  onRotate: () => void
}) {
  return (
    <div className="flex h-10 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
      {showRailToggle ? (
        <IconButton
          label={railsOpen ? "Hide sidebar" : "Show sidebar"}
          aria-pressed={railsOpen}
          onClick={onToggleRails}
        >
          {railsOpen ? <PanelLeftClose /> : <PanelLeftOpen />}
        </IconButton>
      ) : null}
      <span className="px-1 text-xs text-muted-foreground tabular-nums">
        Page {Math.min(currentPage, pageCount)} of {pageCount}
      </span>
      <div className="ml-auto flex items-center gap-1">
        <IconButton label="Zoom out" onClick={onZoomOut}>
          <Minus />
        </IconButton>
        <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
          {Math.round(scale * 100)}%
        </span>
        <IconButton label="Zoom in" onClick={onZoomIn}>
          <Plus />
        </IconButton>
        <IconButton label="Fit width" onClick={onFitWidth}>
          <Maximize />
        </IconButton>
        <IconButton label="Rotate" onClick={onRotate}>
          <RotateCw />
        </IconButton>
        <Separator orientation="vertical" className="mx-1 h-4" />
        <ViewerDownloadControl actions={[downloadAction]} />
      </div>
    </div>
  )
}

function IconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}
