    () => createViewerResource({ kind: "url", url: props.src }),
    [props.src]
  )

  return (
    <ViewerErrorBoundary
      className={props.className}
      download={resource.originalDownload}
      format="pdf"
      onRetry={() => clearDocumentResource(resource.content)}
      resetKey={resource.keys.resource}
      sourceKind={resource.sourceKind}
      variant="inline"
    >
      <React.Suspense
        fallback={<SidebarFallback className={props.className} />}
      >
        <PdfThumbnailSidebarInner {...props} resource={resource} />
      </React.Suspense>
    </ViewerErrorBoundary>
  )
}

function PdfThumbnailSidebarInner({
  resource,
  currentPage,
  onSelectPage,
  width = 120,
  className,
}: PdfThumbnailSidebarProps & {
  resource: ReturnType<typeof createViewerResource>
}) {
  const content = resource.content
  const doc = readDocumentResource(content)
  React.useEffect(() => {
    retainDocumentResource(content, doc)
    return () => releaseDocumentResource(content, doc)
  }, [content, doc])

  return (
    <div
      data-slot="pdf-thumbnail-sidebar"
      className={cn(
        "flex h-full flex-col items-center gap-2 overflow-auto bg-muted/30 p-2",
        className
      )}
    >
      {Array.from({ length: doc.numPages }, (_, i) => (
        <Thumbnail
          key={i}
          doc={doc}
          pageNumber={i + 1}
          width={width}
          active={currentPage === i + 1}
          onSelect={() => onSelectPage?.(i + 1)}
        />
      ))}
    </div>
  )
}

function Thumbnail({
  doc,
  pageNumber,
  width,
  active,
  onSelect,
}: {
  doc: PDFDocumentProxy
  pageNumber: number
  width: number
  active: boolean
  onSelect: () => void
}) {
  const [visible, setVisible] = React.useState(false)

  // Render only once the thumbnail nears the viewport (no effect).
  const observerRef = React.useCallback(
    (el: HTMLButtonElement | null) => {
      if (!el || visible) return
      if (typeof IntersectionObserver === "undefined") {
        setVisible(true)
        return
      }
      const observer = new IntersectionObserver(
        ([entry]) => {
          if (entry.isIntersecting) {
            setVisible(true)
            observer.disconnect()
          }
        },
        { rootMargin: "400px 0px" }
      )
      observer.observe(el)
      return () => observer.disconnect()
    },
    [visible]
  )

  return (
    <button
      ref={observerRef}
      type="button"
      onClick={onSelect}
      data-active={active}
      aria-current={active ? "page" : undefined}
      className="flex flex-shrink-0 flex-col items-center gap-1 outline-none"
    >
      <div
        className={cn(
          "overflow-hidden rounded-sm bg-white ring-2 transition-shadow",
          active ? "ring-primary" : "ring-border"
        )}
        style={{ width, aspectRatio: visible ? undefined : "3 / 4" }}
      >
        {visible ? (
          <React.Suspense fallback={<ThumbSkeleton />}>
            <ThumbnailCanvas doc={doc} pageNumber={pageNumber} width={width} />
          </React.Suspense>
        ) : (
          <ThumbSkeleton />
        )}
      </div>
      <span
        className={cn(
          "text-[10px] tabular-nums",
          active ? "font-semibold text-foreground" : "text-muted-foreground"
        )}
      >
        {pageNumber}
      </span>
    </button>
  )
}

function ThumbnailCanvas({
  doc,
  pageNumber,
  width,
}: {
  doc: PDFDocumentProxy
  pageNumber: number
  width: number
}) {
  const page = readPageResource(doc, pageNumber)
  // Default rotation uses the page's intrinsic /Rotate (correct orientation).
  const viewport = React.useMemo(() => {
    const base = page.getViewport({ scale: 1 })
    return page.getViewport({ scale: width / base.width })
  }, [page, width])
  const dpr = (typeof window !== "undefined" ? window.devicePixelRatio : 1) || 1

  const canvasRef = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return
      const context = canvas.getContext("2d")
      if (!context) return
      canvas.width = getPdfCanvasPixelSize(viewport.width, dpr)
      canvas.height = getPdfCanvasPixelSize(viewport.height, dpr)
      const task = page.render({
        canvas,
        canvasContext: context,
        viewport,
        transform: dpr !== 1 ? [dpr, 0, 0, dpr, 0, 0] : undefined,
      })
      task.promise.catch(() => {
        /* cancelled or failed — ignore */
      })
      return () => task.cancel()
    },
    [page, viewport, dpr]
  )

  return (
    <canvas
      ref={canvasRef}
      style={{ width: viewport.width, height: viewport.height }}
      className="block"
    />
  )
}

function ThumbSkeleton() {
  return (
    <div className="flex aspect-[3/4] w-full items-center justify-center bg-muted">
      <Spinner className="size-3 text-muted-foreground" />
    </div>
  )
}

function SidebarFallback({ className }: { className?: string }) {
  return (
    <div
      className={cn(
        "flex h-full items-center justify-center bg-muted/30",
        className
      )}
    >
      <Spinner className="size-4 text-muted-foreground" />
    </div>
  )
}
