): (props: PageOverlayProps) => React.ReactNode {
  const target = source ? pdfAnchorToTarget(source.anchor) : undefined
  return function PdfSourceOverlay({ pageNumber }: PageOverlayProps) {
    return target && target.page === pageNumber ? (
