                        <React.Suspense fallback={<PageSkeleton />}>
                          <PdfPage
                            document={document}
                            pageNumber={pageNumber}
                            scale={resolvedScale}
                            rotation={rotation}
                            renderOverlay={renderPageOverlay}
                            onSize={setPageSize}
                          />
                        </React.Suspense>
                      </div>
                    )
                  })}
                </div>
              </div>
            </ScrollArea>
          </div>
        </div>
      </div>
    </div>
  )
}
