        {visibleItems.map((item) => (
          <li
            key={item.pageNumber}
            data-index={item.pageIndex}
            className="absolute top-0 left-0 flex w-full justify-center pb-2"
            style={{
              height: item.height,
              transform: `translateY(${item.top}px)`,
            }}
          >
            <PdfThumbnailItem
              doc={doc}
              item={item}
              active={activePage === item.pageNumber}
              itemId={getPdfThumbnailItemId(item.pageNumber)}
              onSelectPage={handleSelectPage}
            />
          </li>
        ))}
      </ol>
    </nav>
  )
}

function getKeyboardTargetPage({
  key,
  page,
  pageCount,
}: {
  key: string
  page: number
  pageCount: number
}) {
  switch (key) {
    case "ArrowUp":
      return Math.max(1, page - 1)
    case "ArrowDown":
      return Math.min(pageCount, page + 1)
    case "Home":
      return 1
    case "End":
      return pageCount
    default:
      return null
  }
}
