              onSelectPage={handleSelectPage}
            />
          </li>
        ))}
      </ol>
    </nav>
  )
}

function getKeyboardTargetPage({
  key,
  page,
  pageCount,
}: {
  key: string
  page: number
  pageCount: number
}) {
  switch (key) {
    case "ArrowUp":
      return Math.max(1, page - 1)
    case "ArrowDown":
