export type ViewerSidebarTriggerProps = ButtonProps & {
  side?: "left" | "right"
}

export function ViewerSidebarTrigger({
  side = "left",
  className,
  disabled,
  loading,
  onClick,
  children,
  size = "icon",
  variant = "ghost",
  "aria-label": ariaLabel = "Toggle sidebar",
