    canToggleSidebar,
    open,
    registeredSidebar,
    resolvedSidebarMode,
    rootId,
    setOpen,
  ])

  const sidebarStateContext = React.useMemo<ViewerSidebarContextValue>(
    () => ({
      state,
      open: effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      mode: resolvedSidebarMode,
      sidebarId,
    }),
    [
      state,
      effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      resolvedSidebarMode,
      sidebarId,
    ]
  )

  const sidebarRegistrationContext =
    React.useMemo<ViewerSidebarRegistrationContextValue>(
      () => ({
        hasSidebar,
        sidebarState: sidebarStateContext,
