export interface PdfViewerProps {
  /** Canonical PDF source. URL sources preserve PDF.js range-loading behavior. */
  source: PdfDocumentSource
  className?: string
  /** Controlled rendered scale; when omitted the viewer fits page width until manually zoomed. */
  scale?: number
  /** Initial uncontrolled scale. Leave unset for fit-to-width. */
  defaultScale?: number
  /** Called when toolbar controls request a scale change. `null` means fit width. */
  onScaleChange?: (scale: number | null) => void
  toolbar?: boolean
  /** Show download actions in this viewer's toolbar/error state. */
  download?: boolean
  /** Render absolutely-positioned overlays (e.g. bbox citations) on each page. */
  renderPageOverlay?: (props: PageOverlayProps) => React.ReactNode
  /** Fired with the 1-based page nearest the top of the viewport as you scroll. */
  onVisiblePageChange?: (page: number) => void
  /** Fired with scroll progress in [0, 1] (for a fine-grained scroll cursor). */
  onScrollProgressChange?: (progress: number) => void
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
}

export type PdfResourceContentProps = Omit<PdfViewerProps, "source"> & {
  resource: ViewerResource
}

export const PdfViewer = React.forwardRef<PdfViewerHandle, PdfViewerProps>(
  function PdfViewer(props, ref) {
    const {
      source,
      className,
      bare = false,
      toolbar = true,
      download = true,
      ...pagesProps
    } = props
    return (
      <PdfViewerProvider source={source}>
        <ViewerRoot bare={bare} className={cn("h-full", className)}>
          <PdfViewerHeader download={download} toolbar={toolbar} />
          <ViewerBody>
            <ViewerSurface>
              <PdfViewerPages
                {...pagesProps}
                bare
                className="h-full"
                download={download}
                ref={ref}
              />
            </ViewerSurface>
          </ViewerBody>
        </ViewerRoot>
      </PdfViewerProvider>
    )
  }
)

export function PdfViewerHeader({
  children,
  className,
  download = true,
  toolbar = true,
}: {
  children?: React.ReactNode
  className?: string
  download?: boolean
  toolbar?: boolean
}) {
  const { currentPage, headerControls, resource } = usePdfViewerHeaderState()
  const label = resource.fileName || "PDF"

  if (children !== undefined) {
    return (
      <ViewerHeader
        className={cn("flex min-h-10 items-center gap-3 px-2 py-1", className)}
      >
        {children}
      </ViewerHeader>
    )
  }

  return (
    <ViewerHeader
      className={cn("flex min-h-10 items-center gap-3 px-2 py-1", className)}
    >
      {toolbar && headerControls ? (
        <ViewerToolbar
          className="h-auto flex-1 border-b-0 bg-transparent px-0"
          title={label}
          position={{
            kind: "page",
            current: headerControls.currentPage,
            total: headerControls.pageCount,
          }}
          zoom={{
            scale: headerControls.scale,
            onZoomOut: headerControls.onZoomOut,
            onZoomIn: headerControls.onZoomIn,
            onFit: headerControls.onFitWidth,
          }}
          rotate={{ onRotate: headerControls.onRotate }}
          downloads={download ? [headerControls.downloadAction] : []}
        />
      ) : (
        <ViewerToolbar
          className="h-auto flex-1 border-b-0 bg-transparent px-0"
          title={label}
          position={
            toolbar && currentPage
              ? { kind: "page", current: currentPage }
              : null
          }
        />
      )}
    </ViewerHeader>
  )
}

export const PdfViewerPages = React.forwardRef<
  PdfViewerHandle,
  Omit<PdfViewerProps, "source">
>(function PdfViewerPages(props, ref) {
  const { resource, setCurrentPage, setViewerHandle } = usePdfViewerPagesState()
  const { onVisiblePageChange } = props
  const handleVisiblePageChange = React.useCallback(
    (page: number) => {
      setCurrentPage(page)
      onVisiblePageChange?.(page)
    },
    [onVisiblePageChange, setCurrentPage]
  )
  const handleRef = React.useCallback(
    (handle: PdfViewerHandle | null) => {
      setViewerHandle(handle)
      if (typeof ref === "function") {
        ref(handle)
        return
      }
      if (ref) ref.current = handle
    },
    [ref, setViewerHandle]
  )

  return (
    <PdfResourceContent
      {...props}
      ref={handleRef}
      resource={resource}
      toolbar={false}
      onVisiblePageChange={handleVisiblePageChange}
    />
  )
})

export const PdfResourceContent = React.forwardRef<
  PdfViewerHandle,
  PdfResourceContentProps
>(function PdfResourceContent(props, ref) {
  const resource = props.resource
  const isClient = useIsClient()

  if (!isClient) {
    return (
      <PdfViewerFallback
        className={props.className}
        bare={props.bare}
        toolbar={props.toolbar}
      />
    )
  }

  return (
    <ViewerErrorBoundary
      className={props.className}
      download={props.download === false ? null : resource.originalDownload}
      format="pdf"
      onRetry={() => clearPdfDocumentResource(resource.content)}
      resetKey={resource.keys.resource}
      sourceKind={resource.sourceKind}
    >
      <React.Suspense
        fallback={
          <PdfViewerFallback
            className={props.className}
            bare={props.bare}
            toolbar={props.toolbar}
          />
        }
      >
        <PdfViewerInner {...props} forwardedRef={ref} resource={resource} />
      </React.Suspense>
    </ViewerErrorBoundary>
  )
})

function PdfViewerInner({
  resource,
  className,
  scale: controlledScale,
  defaultScale,
  onScaleChange,
  toolbar = true,
  download = true,
  renderPageOverlay,
  onVisiblePageChange,
  onScrollProgressChange,
  bare = false,
  forwardedRef,
}: Omit<PdfViewerProps, "source"> & {
  forwardedRef?: React.ForwardedRef<PdfViewerHandle>
  resource: ViewerResource
}) {
  const setHeaderControls = usePdfViewerHeaderControlSetter()
  const content = resource.content
  const document = readPdfDocumentResource(content)
  React.useEffect(() => {
    retainPdfDocumentResource(content, document)
    return () => releasePdfDocumentResource(content, document)
  }, [content, document])

  const firstPage = readPdfPageResource(document, 1)
  const firstPageSize = React.useMemo<PdfPageSize>(() => {
    const viewport = firstPage.getViewport({ scale: 1 })
    return { width: viewport.width, height: viewport.height }
  }, [firstPage])

  const { ref: containerRef, width: containerWidth } = useMeasuredElementWidth()
  const [rotationState, setRotationState] = React.useState<{
    document: typeof document
    value: number
  }>(() => ({ document, value: 0 }))
  const rotation = Object.is(rotationState.document, document)
    ? rotationState.value
    : 0
  const fitPageWidth =
    rotation % 180 === 0 ? firstPageSize.width : firstPageSize.height
  const { resolvedScale, zoomIn, zoomOut, fitWidth } = usePdfScale({
    controlledScale,
    defaultScale,
    onScaleChange,
    containerWidth,
    pageWidth: fitPageWidth,
    resetKey: document,
  })

  const { pageSizeByNumber, setPageSize } = usePdfPageSizes(document)
  const pageLayout = React.useMemo(
    () =>
      createPdfPageLayout({
        pageCount: document.numPages,
        defaultPageSize: firstPageSize,
        pageSizeByNumber,
        scale: resolvedScale,
        rotation,
      }),
    [
      document.numPages,
      firstPageSize,
      pageSizeByNumber,
      resolvedScale,
      rotation,
    ]
  )
  const {
    currentPage,
    viewportElement,
    setViewportElement,
    measureScroll,
    handleScroll,
    scrollToPage,
    scrollToPageArea,
    getViewportElement,
  } = usePdfScroll({
    pageCount: document.numPages,
    layout: pageLayout,
    resetKey: document,
    onVisiblePageChange,
    onScrollProgressChange,
  })
  const handleRotate = React.useCallback(() => {
    setRotationState((state) => ({
      document,
      value:
        ((Object.is(state.document, document) ? state.value : 0) + 90) % 360,
    }))
  }, [document])
  const headerControls = React.useMemo<PdfViewerHeaderControls>(
    () => ({
      currentPage,
      downloadAction: resource.originalDownload,
      onFitWidth: fitWidth,
      onRotate: handleRotate,
      onZoomIn: zoomIn,
      onZoomOut: zoomOut,
      pageCount: document.numPages,
      scale: resolvedScale,
    }),
    [
      currentPage,
      document.numPages,
      fitWidth,
      handleRotate,
      resource.originalDownload,
      resolvedScale,
      zoomIn,
      zoomOut,
    ]
  )
  React.useEffect(() => {
    if (!setHeaderControls) return
    setHeaderControls(headerControls)
    return () => setHeaderControls(null)
  }, [headerControls, setHeaderControls])
  const { visiblePageNumbers, measureVisiblePages } = usePdfPageVirtualization({
    layout: pageLayout,
    resetKey: document,
    viewportElement,
  })

  React.useEffect(() => {
    measureScroll()
  }, [
    document.numPages,
    measureScroll,
    rotation,
    resolvedScale,
    viewportElement,
  ])

  const handleViewportScroll = React.useCallback(() => {
    handleScroll()
    measureVisiblePages()
  }, [handleScroll, measureVisiblePages])

  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      scrollToPage,
      scrollToPageArea,
      getViewportElement,
    }),
    [getViewportElement, scrollToPage, scrollToPageArea]
  )

  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="pdf-viewer"
    >
      {toolbar ? (
        <ViewerToolbar
          position={{
            kind: "page",
            current: currentPage,
            total: document.numPages,
          }}
          zoom={{
            scale: resolvedScale,
            onZoomOut: zoomOut,
            onZoomIn: zoomIn,
            onFit: fitWidth,
          }}
          rotate={{ onRotate: handleRotate }}
          downloads={download ? [resource.originalDownload] : []}
        />
      ) : null}

      <div className="flex min-h-0 flex-1">
        <div className="relative flex min-h-0 min-w-0 flex-1 flex-col">
          <div className="relative flex min-h-0 flex-1 flex-col">
            <ScrollArea
              className="min-h-0 flex-1"
              viewportRef={setViewportElement}
              viewportProps={{ onScroll: handleViewportScroll }}
            >
              <div
                ref={containerRef}
                data-slot="pdf-viewer-fit-width-measure"
                className="relative min-w-0"
              >
                <div
                  data-slot="pdf-viewer-document"
                  className="relative mx-auto"
                  style={{
                    height: pageLayout.totalHeight,
                    minWidth: pageLayout.maxPageWidth,
                  }}
                >
                  {visiblePageNumbers.map((pageNumber) => {
                    const page = getPdfPageLayout(pageLayout, pageNumber)
                    if (!page) return null

                    return (
                      <div
                        key={pageNumber}
                        data-slot="pdf-page-slot"
                        data-page-number={pageNumber}
                        className="absolute left-1/2 flex -translate-x-1/2 items-center justify-center"
                        style={{
                          top: page.offsetTop,
                          width: page.width,
                          minHeight: page.height,
                        }}
                      >
                        <React.Suspense fallback={<PageSkeleton />}>
                          <PdfPage
                            document={document}
                            pageNumber={pageNumber}
                            scale={resolvedScale}
                            rotation={rotation}
                            renderOverlay={renderPageOverlay}
                            onSize={setPageSize}
                          />
                        </React.Suspense>
                      </div>
                    )
                  })}
                </div>
              </div>
            </ScrollArea>
          </div>
        </div>
      </div>
    </div>
  )
}
