export interface PdfViewerProps extends PdfViewerContentProps {
  /** Canonical PDF source. URL sources preserve PDF.js range-loading behavior. */
  source: PdfDocumentSource
}

export const PdfViewer = React.forwardRef<PdfViewerHandle, PdfViewerProps>(
  function PdfViewer(props, ref) {
    const {
      source,
      className,
      bare = false,
      controls = true,
      download = true,
      ...pagesProps
    } = props
    return (
      <FileViewer
        source={source}
        bare={bare}
        className={cn("h-full", className)}
      >
        <PdfViewerProvider>
          <FileViewerHeader>
            <FileViewerTitle />
            <FileViewerMeta />
            {controls ? <FileViewerControls /> : null}
          </FileViewerHeader>
          <FileViewerBody>
            <FileViewerSurface>
              <PdfViewerPages
                {...pagesProps}
                bare
                className="h-full"
