  fitWidth: () => void
  resolvedScale: number
  rotateClockwise: () => void
  zoomIn: () => void
  zoomOut: () => void
}) {
  const onControlsChange = useViewerControlsRegistration()
  const controlsState = React.useMemo<ViewerControlsState>(
    () => ({
      position: {
        kind: "page",
        current: currentPage,
        total: document.numPages,
      },
      zoom: {
        scale: resolvedScale,
        onZoomOut: zoomOut,
        onZoomIn: zoomIn,
        onFit: fitWidth,
      },
      rotate: { onRotate: rotateClockwise },
      downloads: download ? [downloadAction] : [],
    }),
    [
      currentPage,
      document.numPages,
      download,
      downloadAction,
      fitWidth,
      resolvedScale,
      rotateClockwise,
      zoomIn,
      zoomOut,
    ]
  )

  React.useEffect(() => {
    if (!onControlsChange) return
    onControlsChange(controlsState)
    return () => onControlsChange(null)
  }, [onControlsChange, controlsState])
}

function PdfDocumentPagesLayer({
  containerRef,
  document,
  layout,
  pageNumbers,
  renderPageOverlay,
