function usePdfDocumentControlsRegistration({
  currentPage,
  document,
  download,
  downloadAction,
  fitWidth,
  resolvedScale,
  rotateClockwise,
  zoomIn,
  zoomOut,
}: {
  currentPage: number
  document: PdfDocument
  download: boolean
  downloadAction: ViewerResource["originalDownload"]
