      const targetLeft = getPdfPageAreaScrollLeft(viewportElement, {
        pageNumber,
        left: target.left,
        width: target.width,
      })

      viewportElement.scrollTo({
        top: Math.max(0, targetTop),
        ...(targetLeft == null ? null : { left: targetLeft }),
