"content": "export type FileCategory =
  | "pdf"
  | "docx"
  | "xlsx"
  | "pptx"
  | "csv"
  | "image"
  | "markdown"
  | "html"
  | "text"
  | "unsupported"

export type ViewerSource = UrlViewerSource | TextSource | BlobViewerSource

export interface UrlViewerSource {
  kind: "url"
  url: string
  fileName?: string
  mimeType?: string
  downloadUrl?: string
  identityKey?: string
}

export interface TextSource {
  kind: "text"
