  identityKey?: string
}

export interface BlobViewerSource {
  kind: "blob"
  blob: Blob
  identityKey: string
  fileName?: string
  mimeType?: string
  downloadUrl?: string
}

export interface ViewerDescriptor {
  source: ViewerSource
  category: FileCategory
  identityKey: string
  displayName: string
  fileName: string
  mimeType?: string
}

const EXTENSION_CATEGORY: Record<string, FileCategory> = {
  pdf: "pdf",
  docx: "docx",
  xlsx: "xlsx",
  xls: "xlsx",
  xlsm: "xlsx",
  pptx: "pptx",
  csv: "csv",
