          <FileViewerBody>
            <FileViewerSurface>
              <PdfViewerPages
                {...pagesProps}
                bare
                className="h-full"
                download={download}
                ref={ref}
              />
            </FileViewerSurface>
          </FileViewerBody>
        </PdfViewerProvider>
      </FileViewer>
    );
  },
);
